n=struct.unpack('>H',f[4:6])[0]
tables={}
for i in range(n):
    tag,cs,off,ln=struct.unpack('>4sIII',f[12+16*i:28+16*i]); tables[tag.decode()]=(off,ln)
# cmap format 12
off,_=tables['cmap']; nt=struct.unpack('>H',f[off+2:off+4])[0]
cmap={}
for i in range(nt):
    pid,eid,so=struct.unpack('>HHI',f[off+4+8*i:off+12+8*i]); s=off+so
    if struct.unpack('>H',f[s:s+2])[0]==12:
        ng=struct.unpack('>I',f[s+12:s+16])[0]
        for g in range(ng):
            a,b,gid=struct.unpack('>III',f[s+16+12*g:s+28+12*g])
            for c in range(a,b+1): cmap[c]=gid+(c-a)
        break
po,_=tables['post']
assert struct.unpack('>I',f[po:po+4])[0]==0x20000
num=struct.unpack('>H',f[po+32:po+34])[0]
idx=struct.unpack('>%dH'%num,f[po+34:po+34+2*num]); p=po+34+2*num; names=[]
while len(names)< (max(idx)-257 if max(idx)>257 else 0)+1:
    l=f[p]; names.append(f[p+1:p+1+l].decode()); p+=1+l
for c in (0xf05c8,0xf1853):
    g=cmap.get(c); i=idx[g]; print(hex(c), names[i-258] if i>=258 else 'std')
